const BASE = 'http://localhost:8080/api';

const authHeaders = () => ({
  'Content-Type': 'application/json',
  'Authorization': `Bearer ${localStorage.getItem('token') || ''}`,
});

export const loginApi = (employeeId, password) => {
  if (employeeId === 'EMP001' && password === 'bank@1234') {
    return Promise.resolve({
      json: () => Promise.resolve({ success: true, token: 'demo-token', name: 'Demo Employee', employeeId }),
    });
  }
  return Promise.resolve({
    json: () => Promise.resolve({ success: false, message: 'Invalid Employee ID or Password.' }),
  });
};

export const createAccountApi = (data) =>
  fetch(`${BASE}/accounts`, {
    method: 'POST',
    headers: authHeaders(),
    body: JSON.stringify(data),
  });

export const depositApi = (data) =>
  fetch(`${BASE}/transactions/deposit`, {
    method: 'POST',
    headers: authHeaders(),
    body: JSON.stringify(data),
  });

export const getAccountsApi = () =>
  fetch(`${BASE}/accounts`, { headers: authHeaders() });

export const getTransactionsApi = () =>
  fetch(`${BASE}/transactions`, { headers: authHeaders() });
